head.script:
scwin.gVar = {
    "cID" : ""
}



scwin.onpageload = function () {
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제 (커스텀 id 가능 -> scwin.target1 레퍼런스로 제거)
    if (typeof scwin.target1 !== 'undefined' && scwin.target1) {
        scwin.target1.remove();
    }

    // 조건 설정
    let cID = scwin.gVar["cID"];

    // getID 는 id 설정 유무에 따른 반환값 확인이 목적이므로 pageList 를 직접 생성
    //  - cID 가 빈값이면 dynamicCreate 가 내부 규칙으로 임의 id 자동 부여 (createBasicPageList 는 빈값 시 target1 로 고정되어 부적합)
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '<w2:pageList ' + strNameSpace + ' pageSize="10" displayButtonType="display" displayFormat="#" style="width:350px; height:21px;"></w2:pageList>';

    // base(common_M)가 objParent.scwin.target1 로 접근하므로 scwin.target1 에 생성된 pageList 를 설정 (빈 cID -> 자동 id)
    scwin.target1 = await $p.dynamicCreate(cID, "pageList", strTarget, grp_comp);

    scwin.target1.setCount(10);
}
